                local mode = s.input.mode == "capture" and "键盘接管" or "按键只读/透传"
                view.info((s.paused and "已暂停" or "运行中") .. " | " .. mode .. " | 实体 " .. (s.world and #s.world.list or 0) .. " | Music " .. (s.music and s.music.backend or "silent"))
