-- game module: fireworks
gameModules["fireworks"]=(function()
-- Game-owned firework choreography and repeatable performance trials.
-- Physics, pooling, emission and projection live in the shared 3D particle system.
local F={}
F.kinds={{id="peony",name="星辉礼花"},{id="ring",name="奥术星环"},{id="willow",name="鎏金垂柳"},{id="fountain",name="翡翠喷泉"},{id="crackle",name="连环爆裂"}}
function F.new(ctx,scene,getOrder,getSkin)
    local M,fx=ctx.scene3d.math,scene.particles
    local self={selected="peony",intensity=2,testing=false,message="选择烟花，或运行四阶段性能对照。",rewards=0}
    local queue,time,serial,stage,nextLaunch={},0,0,0,0
    local intensity={.55,1,3};local phaseLabels={"空场基线","低密度","标准密度","高密度"}
    local settings=ctx.content.fireworksLab or {};local duration=settings.duration or 5;local warmup=settings.warmup or 1
    local function schedule(delay,fn)
        if #queue>=96 then return false end
        queue[#queue+1]={at=time+delay,fn=fn};return true
    end
    local function launch(kind,level,side)
        serial=serial+1;local seed=serial*7919;local factor=intensity[level]
        -- Place the launch pads beside the current view of the cube, then keep
        -- their trajectories in world space even if the player orbits the camera.
        local camera=scene.getCamera();local toward=M.unit(M.sub(camera.position,camera.target))
        local right=M.unit(M.cross(M.vec(0,1,0),toward))
        local start=M.add(camera.target,M.add(M.mul(right,(side or (serial%2==0 and -2.15 or 2.15))*1.25),M.mul(toward,serial%3==0 and -.5 or 1.6)))
        start.y=-1.35
        if kind=="fountain" then
            fx.start("fountain",{position=start,countScale=factor,seed=seed});return
        end
        local flight=.65;local rise=M.vec(0,3.5,0);local acceleration=M.vec(0,-2,0)
        fx.start("rocket_trail",{position=start,emitterVelocity=rise,emitterAcceleration=acceleration,duration=flight,countScale=factor,seed=seed})
        local center=M.add(start,M.add(M.mul(rise,flight),M.mul(acceleration,.5*flight*flight)))
        schedule(flight,function()
            fx.burst(kind,{position=center,countScale=factor,seed=seed+1})
            fx.burst("flash",{position=center,seed=seed+2})
            if kind=="crackle" then
                for i=1,7 do
                    local theta=i*2*math.pi/7
                    local p=M.add(center,M.vec(math.cos(theta)*.65,math.sin(theta)*.65,(i%3-1)*.5))
                    schedule(.16+i*.065,function()fx.burst("crackle",{position=p,countScale=factor*.6,seed=seed+i*17})end)
                end
            end
        end)
    end
    function self.stop(reason)
        if self.ownsPhase and ctx.perf.isRunning()then ctx.perf.finish(reason or "cancelled")end
        self.ownsPhase=false
        self.testing=false;stage=0;queue={};fx.clear()
        self.message=reason=="complete" and "对照完成，可导出每阶段的帧耗时与粒子统计。" or "已停止烟花。"
    end
    function self.select(id)
        for _,kind in ipairs(F.kinds)do if kind.id==id then self.selected=id;return true end end;return false
    end
    function self.setIntensity(level)if level>=1 and level<=3 then self.intensity=level end end
    function self.preview()
        if self.testing or ctx.session.isPaused()then return false end
        queue={};fx.clear();fx.resetStats()
        ctx.perf.begin("fireworks.preview",{kind="particles3d",pattern=self.selected,intensity=self.intensity,order=getOrder()},{warmup=.2,duration=5});self.ownsPhase=true
        launch(self.selected,self.intensity)
        self.message="正在燃放，可旋转视角观察空间轨迹和遮挡。";return true
    end
    function self.show(reason)
        if self.testing or ctx.session.isPaused()then return false end
        queue={};fx.clear();fx.resetStats()
        ctx.perf.begin(reason and "fireworks.reward" or "fireworks.mixed",{kind="particles3d",pattern="five_types",intensity=self.intensity,order=getOrder(),reason=reason},{warmup=.2,duration=6});self.ownsPhase=true
        for i,kind in ipairs(F.kinds)do schedule((i-1)*.55,function()launch(kind.id,self.intensity,i%2==0 and -2.15 or 2.15)end)end
        self.message="五式烟花依次燃放。";return true
    end
    function self.celebrate(reason)
        if self.testing then return end
        self.rewards=self.rewards+1;self.show(reason)
        ctx.perf.note("fireworks.reward",{reason=reason,sequence=self.rewards,order=getOrder()})
    end
    local function phase()
        queue={};fx.clear();fx.resetStats();serial=0;nextLaunch=time
        ctx.perf.begin("fireworks."..({"baseline","low","normal","high"})[stage],
            {kind="particles3d",order=getOrder(),skin=getSkin and getSkin() or "classic",pattern="five_types",intensity=stage-1,
                camera=scene.getCamera(),seed=7919,countersScope="phase_including_warmup",cubeMotion="static"},
            {warmup=warmup,duration=duration})
        self.ownsPhase=true
        self.message=phaseLabels[stage].."：固定镜头与魔方，正在采样。"
    end
    function self.benchmark()
        if self.testing or ctx.session.isPaused()then return false end
        self.testing=true;stage=1;phase();return true
    end
    function self.update(dt)
        time=time+dt
        -- Remove ready tasks before invoking them: crackles can schedule child bursts.
        local ready={}
        for i=#queue,1,-1 do if queue[i].at<=time then ready[#ready+1]=table.remove(queue,i)end end
        for i=#ready,1,-1 do ready[i].fn()end
        if self.testing then
            if not ctx.perf.isRunning()then
                stage=stage+1
                if stage>4 then self.stop("complete");return else phase()end
            end
            if stage>1 and time>=nextLaunch then
                nextLaunch=time+(stage==4 and .18 or .55)
                local kind=F.kinds[serial%#F.kinds+1];launch(kind.id,stage-1)
            end
        end
    end
    function self.onPause()
        if self.testing then self.testing=false;stage=0;queue={};self.message="测试已中断；已完成的阶段仍可导出。"end
    end
    function self.snapshot()
        local perf=ctx.perf.snapshot();local last=perf.last
        return {selected=self.selected,intensity=self.intensity,testing=self.testing,message=self.message,
            phase=stage>0 and phaseLabels[stage] or "",stats=fx.stats(),perf=perf,
            metrics=perf.metrics or (last and last.metrics) or {},rewards=self.rewards,
            totalSeconds=4*(duration+warmup)}
    end
    return self
end
return F

end)()
-- game module: geometry
gameModules["geometry"]=(function()
-- Procedural stone, brass and gemstone faces: no external texture installation.
local A={}
A.colors={U={.90,.92,.84,1},D={1,.73,.14,1},R={.86,.17,.15,1},L={1,.39,.08,1},F={.12,.72,.43,1},B={.13,.43,.94,1}}
A.names={U="月石 · 白",D="圣光 · 金",R="烈焰 · 红",L="琥珀 · 橙",F="翡翠 · 绿",B="寒霜 · 蓝"}
A.faceTextures={U="crystal",D="moon",R="trident",L="shell",F="wave",B="whirlpool"}
local faceAxes={R={{0,0,-1},{0,1,0}},L={{0,0,1},{0,1,0}},U={{1,0,0},{0,0,-1}},D={{1,0,0},{0,0,1}},F={{1,0,0},{0,1,0}},B={{-1,0,0},{0,1,0}}}
function A.registerSkin(scene,pixels)
    for _,face in ipairs(pixels.faces)do if not scene.pixelTextures[face.id]then
        assert(scene.definePixelTexture(face.id,{width=pixels.width,height=pixels.height,codec=pixels.codec,palette=pixels.palette,data=face.data}))
    end end
end
function A.mesh(c,api,puzzle,skin,n)
    local M=api.math;local mesh=api.boxMesh(.93,{.065,.073,.082,1});local bindings={}
    if skin=="tidal" then
        for i,face in ipairs({"B","F","L","R","U","D"})do mesh.faces[i].surfaceGroup=face end
    end
    local function quad(normal,u,v,depth,cx,cy,rx,ry,color,tag)
        local start=#mesh.vertices
        for _,corner in ipairs({{-1,-1},{1,-1},{1,1},{-1,1}})do
            mesh.vertices[#mesh.vertices+1]=M.add(M.mul(normal,depth),M.add(M.mul(u,cx+corner[1]*rx),M.mul(v,cy+corner[2]*ry)))
        end
        mesh.faces[#mesh.faces+1]={start+1,start+2,start+3,start+4,color=color,tag=tag}
        if skin=="tidal" then mesh.faces[#mesh.faces].surfaceGroup=tag end
        return #mesh.faces
    end
    for _,face in ipairs({"R","L","U","D","F","B"})do if c.stickers[face]then
        local normal=puzzle.normals[face];local uv=faceAxes[face]
        local u,v=M.vec(unpack(uv[1])),M.vec(unpack(uv[2]))
        if skin=="tidal" then
            -- Keep the original face color as a thin gameplay-readable rim.
            quad(normal,u,v,.467,0,0,.435,.435,A.colors[face],face)
            local at=quad(normal,u,v,.469,0,0,.414,.414,{1,1,1,1},face)
            local col=(M.dot(c.home,u)+n-1)/2;local row=(n-1-M.dot(c.home,v))/2
            local l,r,t,b=col/n,(col+1)/n,row/n,(row+1)/n
            mesh.faces[at].uv={{u=l,v=b},{u=r,v=b},{u=r,v=t},{u=l,v=t}}
            bindings[at]=A.faceTextures[face]
        else
        quad(normal,u,v,.467,0,0,.423,.423,{.48,.35,.16,1},face)
        quad(normal,u,v,.469,0,0,.381,.381,A.colors[face],face)
        -- A small facet near the top edge reads as a cut gem under the light.
        local color=A.colors[face];local shine={math.min(1,color[1]*.55+.45),math.min(1,color[2]*.55+.45),math.min(1,color[3]*.55+.45),1}
        quad(normal,u,v,.471,0,.335,.325,.018,shine,face)
        end
    end end
    return mesh,bindings
end
return A

end)()
-- game module: materials
gameModules["materials"]=(function()
-- Three independent subjects exercise embedded pixel materials and original UVs.
local L={}
function L.new(ctx,scene,art)
    local M=ctx.scene3d.math
    local self={active=false,selected=1,rotation=0,spinning=false,message="点阵经 UV 映射到模型表面；不加载 PNG。"}
    local registered=false;local angle=0
    local subjects={{id="material_cube",name="海潮符文匣",texture=1,rotation=0},{id="material_obelisk",name="潮汐方碑",texture=3,rotation=0},{id="material_pyramid",name="仪式晶石",texture=5,rotation=0}}
    local positions={M.vec(-2.1,0,0),M.vec(0,0,0),M.vec(2.1,0,0)}
    local function box()
        local mesh=ctx.scene3d.boxMesh(1,{1,1,1,1})
        for _,f in ipairs(mesh.faces)do
            local a,b,c=mesh.vertices[f[1]],mesh.vertices[f[2]],mesh.vertices[f[3]]
            local normal=M.unit(M.cross(M.sub(b,a),M.sub(c,a)));local right,up
            if math.abs(normal.y)>.5 then right=M.vec(1,0,0);up=M.vec(0,0,-normal.y)
            else right=M.cross(M.vec(0,1,0),normal);up=M.vec(0,1,0)end
            f.uv={};for _,index in ipairs(f)do local v=mesh.vertices[index];f.uv[#f.uv+1]={u=.5+M.dot(v,right),v=.5-M.dot(v,up)}end
        end
        return mesh
    end
    local function pyramid()
        return {vertices={M.vec(-.6,-.7,-.6),M.vec(.6,-.7,-.6),M.vec(.6,-.7,.6),M.vec(-.6,-.7,.6),M.vec(0,.9,0)},
            faces={{4,3,5},{3,2,5},{2,1,5},{1,4,5},{1,2,3,4}}}
    end
    local function bind(index)
        local subject=subjects[index];local bindings={}
        local mesh=scene.get(subject.id).mesh
        for i=1,#mesh.faces do
            local texture=subject.sixFaces and ((i-1)%6+1) or subject.texture
            bindings[i]={texture=art.faces[texture].id,rotation=subject.rotation}
        end
        local ok,why=scene.setPixelMaterials(subject.id,bindings)
        self.message=ok and (subject.name.."：点阵材质已绑定。") or ("材质未应用："..tostring(why))
        return ok
    end
    function self.enter()
        if not registered then
            for _,face in ipairs(art.faces)do
                if not scene.pixelTextures[face.id]then
                assert(scene.definePixelTexture(face.id,{width=art.width,height=art.height,codec=art.codec,palette=art.palette,data=face.data}))
                end
            end
            registered=true
        end
        scene.clear();self.active=true;self.spinning=false;angle=.3
        scene.create("material_group",{})
        for i,subject in ipairs(subjects)do
            scene.create(subject.id,{parent="material_group",mesh=i==3 and pyramid() or box(),position=positions[i],
                scale=i==1 and M.vec(1.4,1.4,1.4) or i==2 and M.vec(1.05,2.1,1.05) or M.vec(1.2,1.2,1.2),rotation=M.vec(0,.3,0),tag=subject.name})
            subject.sixFaces=i==1;subject.rotation=0
            assert(bind(i),"pixel material scene exceeds its face budget")
        end
        scene.orbit(.27,.24,5.8,M.vec())
        self.message="三个主体已绑定内嵌点阵；可换图、旋转 UV 或转动模型。"
    end
    function self.leave()self.active=false;self.spinning=false;scene.clear()end
    function self.select(index)if subjects[index]then self.selected=index;angle=scene.get(subjects[index].id).rotation.y;self.message="已选择："..subjects[index].name end end
    function self.pick(hit)for i,s in ipairs(subjects)do if s.id==hit.id then self.select(i);return true end end;return false end
    function self.texture(index)
        local subject=subjects[self.selected];local old,six=subject.texture,subject.sixFaces
        subject.texture=index;subject.sixFaces=false;local ok=bind(self.selected)
        if not ok then subject.texture=old;subject.sixFaces=six end;return ok
    end
    function self.sixFaces()
        local subject=subjects[self.selected];local old=subject.sixFaces;subject.sixFaces=true
        local ok=bind(self.selected);if not ok then subject.sixFaces=old end;return ok
    end
    function self.rotateUV()
        local subject=subjects[self.selected];local old=subject.rotation;subject.rotation=(old+1)%4
        local ok=bind(self.selected);if not ok then subject.rotation=old end;return ok
    end
    function self.removeMaterial()
        local subject=subjects[self.selected];scene.setPixelMaterials(subject.id,nil);subject.sixFaces=false
        self.message="已解除像素绑定；模型几何仍然保留。"
    end
    function self.toggleSpin()self.spinning=not self.spinning;angle=scene.get(subjects[self.selected].id).rotation.y end
    function self.rotateGroup()
        local rotation=scene.get("material_group").rotation
        scene.setTransform("material_group",{rotation=M.vec(0,rotation.y+math.pi/4,0)})
        self.message="整组转动45°；各主体的点阵绑定保持不变。"
    end
    function self.update(dt)
        if self.active and self.spinning then
            angle=angle+dt*.55
            scene.setTransform(subjects[self.selected].id,{rotation=M.vec(math.sin(angle*.5)*.2,angle,0)})
