        end end
        return {selected=self.selected,name=subject.name,texture=subject.texture,sixFaces=subject.sixFaces,uvRotation=subject.rotation,
            bound=self.active and scene.get(subject.id).pixelBindings~=nil,spinning=self.spinning,message=self.message,faces=art.faces,subjects=subjects,labels=labels,rectangles=rects,encodedBytes=encoded,stats=scene.stats()}
    end
    return self
end
return L

end)()
-- game module: pixel_art
gameModules["pixel_art"]=(function()
-- Generated from editable integer pixel shapes in tools/build-tidal-pixels.py.
